/**
 * The English-pattern deck (Loren Osborn, CC0, via Wikimedia Commons) — the
 * first Deck implementation. Its manifest is generated by scripts/build-deck.ts;
 * art lives under public/assets/decks/english/ and ships with the build.
 */
import { deckFromManifest, type Deck, type DeckManifest } from "./deck.ts";
import manifest from "./english-manifest.json";

export const ENGLISH_DIR = "assets/decks/english";

/** The English deck, built from its generated manifest. */
export function englishDeck(): Deck {
  return deckFromManifest(ENGLISH_DIR, manifest as unknown as DeckManifest);
}